import type { ColumnSpec } from './columns.js';
import { sqlName } from './columns.js';
import type { Entity } from './entity.js';

/**
 * Turn entities into the source of `tgcloud/schema.js`, the single schema file
 * tgcloud reads for migrations. The output only imports `sdk/db`.
 */
export function generateSchemaJs(entities: readonly Entity<any, any>[]): string {
  checkDuplicates(entities);
  const used = new Set<string>(['table']);
  const blocks = entities.map((e) => emitTable(e, used));
  const imports = [...used].sort();
  return [
    '// AUTO-GENERATED by tgless from your entity() declarations. Do not edit;',
    '// change the entities in src/ and run `tgless build`.',
    `import { ${imports.join(', ')} } from 'sdk/db';`,
    '',
    blocks.join('\n\n'),
    '',
  ].join('\n');
}

function checkDuplicates(entities: readonly Entity<any, any>[]) {
  const tables = new Set<string>();
  const exports = new Set<string>();
  for (const e of entities) {
    if (tables.has(e.tableName)) throw new Error(`Table "${e.tableName}" is declared by more than one entity().`);
    if (exports.has(e.exportName)) {
      throw new Error(`Two entities map to the schema export "${e.exportName}". Set options.exportName on one of them.`);
    }
    tables.add(e.tableName);
    exports.add(e.exportName);
  }
}

const str = (s: string) => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
/** Embed raw SQL in a `sql` template literal (no interpolation). */
const rawSql = (s: string) => 'sql`' + s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${') + '`';

function factory(spec: ColumnSpec): string {
  return spec.kind;
}

function emitColumn(key: string, spec: ColumnSpec, used: Set<string>): string {
  const fn = factory(spec);
  used.add(fn);
  const args = [str(sqlName(key, spec))];
  if (spec.mode) args.push(`{ mode: '${spec.mode}' }`);
  let out = `${fn}(${args.join(', ')})`;
  if (spec.primary) out += spec.autoIncrement ? '.primaryKey({ autoIncrement: true })' : '.primaryKey()';
  if (spec.notNull && !spec.primary && !spec.generated) out += '.notNull()';
  if (spec.unique) out += '.unique()';
  if (spec.defaultSql !== undefined) {
    used.add('sql');
    out += `.default(${rawSql(spec.defaultSql)})`;
  } else if (spec.default !== undefined) {
    out += `.default(${literal(spec.default.value)})`;
  }
  if (spec.generated) {
    used.add('sql');
    out += `.generatedAlwaysAs(${rawSql(spec.generated.sql)}, { mode: '${spec.generated.mode}' })`;
  }
  if (spec.constraint) out += `.constraint(${str(spec.constraint)})`;
  if (spec.deprecated !== undefined) out += `.deprecated(${str(spec.deprecated)})`;
  return out;
}

function literal(v: unknown): string {
  if (v instanceof Date) return String(Math.floor(v.getTime() / 1000));
  if (typeof v === 'string') return str(v);
  return JSON.stringify(v);
}

function emitTable(e: Entity<any, any>, used: Set<string>): string {
  const lines: string[] = [];
  const cols = Object.entries(e.columns) as [string, { spec: ColumnSpec }][];
  for (const [key, col] of cols) lines.push(`  ${key}: ${emitColumn(key, col.spec, used)},`);

  const extras: string[] = [];
  const t = e.tableName;
  for (const [key, col] of cols) {
    const spec = col.spec;
    if (spec.deprecated !== undefined) continue;
    if (spec.index) {
      used.add('index');
      const name = typeof spec.index === 'string' ? spec.index : `idx_${t}_${sqlName(key, spec)}`;
      extras.push(`    ${ident(name)}: index(${str(name)}).on(t.${key}),`);
    }
    if (spec.enumValues) {
      used.add('check');
      used.add('sql');
      const name = `chk_${t}_${sqlName(key, spec)}`;
      const list = spec.enumValues.map((v) => `'${v.replace(/'/g, "''")}'`).join(', ');
      const nullable = spec.notNull ? '' : ` or \${t.${key}} is null`;
      extras.push(
        `    ${ident(name)}: check(${str(name)}, sql\`\${t.${key}} in (${list.replace(/`/g, '\\`')})${nullable}\`),`,
      );
    }
  }
  const opts = e.options;
  if (opts.primaryKey?.length) {
    used.add('primaryKey');
    extras.push(`    pk: primaryKey({ columns: [${opts.primaryKey.map((k: string) => `t.${k}`).join(', ')}] }),`);
  }
  for (const raw of opts.indexes ?? []) {
    const idx = Array.isArray(raw) ? { columns: raw } : raw;
    const fn = idx.unique ? 'uniqueIndex' : 'index';
    used.add(fn);
    const name = idx.name ?? `${idx.unique ? 'uidx' : 'idx'}_${t}_${idx.columns.map((k: string) => e.sqlColumnName(k)).join('_')}`;
    let expr = `${fn}(${str(name)}).on(${idx.columns.map((k: string) => `t.${k}`).join(', ')})`;
    if (idx.where) {
      used.add('sql');
      expr += `.where(${rawSql(idx.where)})`;
    }
    extras.push(`    ${ident(name)}: ${expr},`);
  }
  for (const [name, expr] of Object.entries(opts.checks ?? {})) {
    used.add('check');
    used.add('sql');
    extras.push(`    ${ident(name)}: check(${str(name)}, ${rawSql(expr as string)}),`);
  }

  let out = `export const ${e.exportName} = table(${str(t)}, {\n${lines.join('\n')}\n}`;
  if (extras.length) out += `, (t) => ({\n${extras.join('\n')}\n  })`;
  out += ')';
  if (opts.strict) out += '.strict()';
  if (opts.withoutRowid) out += '.withoutRowid()';
  if (opts.deprecated !== undefined) out += `.deprecated(${str(opts.deprecated)})`;
  return out + ';';
}

function ident(name: string) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : str(name);
}
